<div class="fight-ground-block"><div class="fight-my-card-block-line"><div class="fight-my-card-line-one" v-for="line in [1,1,1]"></div></div><div class="fight-my-card-block"><div class="fight-my-card-one" v-for="(one,index) in props.allMes.allMesMy.cardGroundList" :style="index===choicedMyCardIndex?'background:#eee':''" @click="choiceCard(index)"><el-tooltip effect="light" placement="top"><template #content> <div style="max-width: 200px;font-size: 12px;color:#666;">{{one.name+":  "+one.desc}}</div></template><div class="fight-my-card-one-img"></div></el-tooltip></div></div><div class="fight-my-cat"><Cat></Cat></div><div class="fight-bot-card-block-line"><div class="fight-bot-card-line-one" v-for="line in [1,1,1]"></div></div><div class="fight-bot-card-block"><div class="fight-bot-card-one" v-for="one in props.allMes.allMesBot.cardGroundList"><div class="fight-bot-card-one-img"></div></div></div><div class="fight-bot-cat"><Cat></Cat></div><div class="fight-all-card-block"><div class="fight-all-card-num">{{props.allMes.cardList.length}}</div><div class="fight-all-card-text">卡池</div></div><div class="fight-used-card-block"><div class="fight-used-card-num">{{props.allMes.cardUsedList.length}}</div><div class="fight-used-card-text">墓地</div></div><div class="fight-chain-block"><div class="fight-chain" v-for="chain in props.allMes.chain"> <el-tooltip effect="light" placement="right"><template #content> <div style="max-width: 200px;font-size: 12px;color:#666;">{{chain.card.desc}}</div></template><div class="fight-chain-text">{{getNameOnce(chain.card.name)}}</div></el-tooltip></div></div></div>